import{_ as p,a0 as a,w as l,s,ao as d,I as r,x as t,a1 as n,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"在 Linux 中怎樣使用cp命令合併目錄樹 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 中怎樣使用cp命令合併目錄樹 | LCTT (201407) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 中怎樣使用cp命令合併目錄樹 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 中怎樣使用cp命令合併目錄樹 | LCTT (201407) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201407/20140724 How to Merge Directory Trees in Linux using cp Command","title":"在 Linux 中怎樣使用cp命令合併目錄樹","tag":"201407","desc":""},"relativePath":"201407/20140724 How to Merge Directory Trees in Linux using cp Command.md","filePath":"[post].md"}'),m={name:"201407/20140724 How to Merge Directory Trees in Linux using cp Command.md"};function u(c,e,g,x,h,_){const i=a("Link");return l(),s("div",null,[e[13]||(e[13]=d('<h1 id="在-linux-中怎樣使用cp命令合併目錄樹" tabindex="-1">在 Linux 中怎樣使用cp命令合併目錄樹 <a class="header-anchor" href="#在-linux-中怎樣使用cp命令合併目錄樹" aria-label="Permalink to “在 Linux 中怎樣使用cp命令合併目錄樹”">​</a></h1><p>怎樣將兩個佈局相似的目錄樹合併成一個新的目錄樹？為理解該問題讓我們思考下面的例子.</p><p>假設 dir1 和 dir2 目錄中分別有3個子目錄a,b和c.目錄佈局如下所示:</p><p><img src="http://linoxide.com/wp-content/uploads/2014/07/01.merge_dir_layout.png" alt="Layout of input directories"> 輸入目錄佈局</p><p>在目錄a,b和c中有一些文件，tree命令的輸出將能更好的説明:</p><p><img src="http://linoxide.com/wp-content/uploads/2014/07/02.merge_file_layout.png" alt="Layout of files"> 文件佈局</p><h3 id="_1-使用cp命令創建合併" tabindex="-1">1. 使用cp命令創建合併: <a class="header-anchor" href="#_1-使用cp命令創建合併" aria-label="Permalink to “1. 使用cp命令創建合併:”">​</a></h3><p>現在我們將這兩個目錄合併成一個名為&quot;merged&quot;新的目錄中.完成上述操作最簡單的方式就是遞歸複製目錄，如下圖所示:</p><p><img src="http://linoxide.com/wp-content/uploads/2014/07/03.merge_cp_recursive.png" alt="Copy directories recursively to create new merge"> 遞歸複製完成新的合併</p><h4 id="_1-1-cp命令和替換帶來的問題" tabindex="-1">1.1 cp命令和替換帶來的問題: <a class="header-anchor" href="#_1-1-cp命令和替換帶來的問題" aria-label="Permalink to “1.1 cp命令和替換帶來的問題:”">​</a></h4><p>這種方式所帶來的問題是該合併目錄中所創建的文件為原文件的副本，並非原文件本身.別急, (你可能正在問自己) 如果不是原文件又有什麼問題? 要回答你的問題，考慮下你有很多大文件的情況.那種情形下，複製所有的文件可能花費數小時.</p><p>現在讓我們回到剛那問題上，且嘗試使用mv命令而不是cp命令.</p><p><img src="http://linoxide.com/wp-content/uploads/2014/07/04.merge_mv_recursive.png" alt="Attempt to merge with mv command"> 企圖使用mv命令進行合併操作</p><p>這些目錄不能被合併.因此我們不能像這樣使用mv命令去合併目錄. 現在你該怎樣將原文件保存到&quot;merged&quot;目錄中?</p><h3 id="_2-解決方法" tabindex="-1">2. 解決方法: <a class="header-anchor" href="#_2-解決方法" aria-label="Permalink to “2. 解決方法:”">​</a></h3><p>cp命令有一個非常有用的選項來幫助我們擺脱這種狀況. cp命令的-l 或 --link選項能夠創建硬鏈接而非原文件副本.讓我們嘗試一下.</p><p>在我們嘗試cp命令的硬鏈接選項前，讓我們查看一下原文件的inode號碼. 可通過tree命令--inodes選項來查看inodes:</p><p><img src="http://linoxide.com/wp-content/uploads/2014/07/05.merge_display_inodes.png" alt="Display inodes of original files"> 原文件的inodes</p><p>現在我們有了inodes的列表，對於cp命令可通過--link選項創建硬鏈接:</p><p><img src="http://linoxide.com/wp-content/uploads/2014/07/06.merge_create_links.png" alt="Merge directories with hard links"> 使用硬鏈接合併的目錄</p><h4 id="_2-1-驗證文件" tabindex="-1">2.1 驗證文件: <a class="header-anchor" href="#_2-1-驗證文件" aria-label="Permalink to “2.1 驗證文件:”">​</a></h4><p>現在文件已經被複制，讓我們驗證一下inodes是否和原文件匹配:</p><p><img src="http://linoxide.com/wp-content/uploads/2014/07/07.merge_verify_inodes.png" alt="Verify Inodes"> Verify Inodes</p><h4 id="_2-2-清除" tabindex="-1">2.2 清除: <a class="header-anchor" href="#_2-2-清除" aria-label="Permalink to “2.2 清除:”">​</a></h4><p>正如你所看到的，這些文件的inodes和原文件的一樣.現在問題已經被解決，且 原文件已被複制到合併目錄中.現在我們能夠移除dir1和dir2目錄.</p><p><img src="http://linoxide.com/wp-content/uploads/2014/07/08.merge_cleanup.png" alt="Remove original directories"> 移除原始目錄</p><hr>',27)),r("p",null,[e[1]||(e[1]=t("via: ",-1)),n(i,{href:"http://linoxide.com/linux-command/merge-directory-trees-linux/"},{default:o(()=>[...e[0]||(e[0]=[t("http://linoxide.com/linux-command/merge-directory-trees-linux/",-1)])]),_:1})]),r("p",null,[e[3]||(e[3]=t("原文作者：",-1)),n(i,{href:"http://linoxide.com/author/raghu/"},{default:o(()=>[...e[2]||(e[2]=[t("Raghu",-1)])]),_:1})]),r("p",null,[e[6]||(e[6]=t("譯者：",-1)),n(i,{href:"https://github.com/hunanchenxingyu"},{default:o(()=>[...e[4]||(e[4]=[t("hunanchenxingyu",-1)])]),_:1}),e[7]||(e[7]=t(" 校對：",-1)),n(i,{href:"https://github.com/carolinewuyan"},{default:o(()=>[...e[5]||(e[5]=[t("Caroline",-1)])]),_:1})]),r("p",null,[e[10]||(e[10]=t("本文由 ",-1)),n(i,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[8]||(e[8]=[t("LCTT",-1)])]),_:1}),e[11]||(e[11]=t(" 原創翻譯，",-1)),n(i,{href:"http://linux.cn/"},{default:o(()=>[...e[9]||(e[9]=[t("Linux中國",-1)])]),_:1}),e[12]||(e[12]=t(" 榮譽推出",-1))])])}const C=p(m,[["render",u]]);export{L as __pageData,C as default};
